// --- Video Generation (Veo) ---

export const generateHologram = async (
  imageBase64: string,
  prompt: string,
  aspectRatio: '16:9' | '9:16'
): Promise<string | null> => {
  try {
    // Create a new client instance as per Veo guidelines to ensure latest API key is used
    const veoClient = new GoogleGenAI({ apiKey: process.env.API_KEY });

    let operation = await veoClient.models.generateVideos({
      model: 'veo-3.1-fast-generate-preview',
      prompt: prompt,
      image: {
        imageBytes: imageBase64,
        mimeType: 'image/jpeg', // Default for uploaded images
      },
      config: {
        numberOfVideos: 1,
        resolution: '720p',
        aspectRatio: aspectRatio,
      }
    });

    while (!operation.done) {
      await new Promise(resolve => setTimeout(resolve, 5000));
      operation = await veoClient.operations.getVideosOperation({operation: operation});
    }

    const videoUri = operation.response?.generatedVideos?.[0]?.video?.uri;
    if (videoUri) {
      // Append API key for download
      return `${videoUri}&key=${process.env.API_KEY}`;
    }
    return null;

  } catch (error) {
    console.error("Veo Generation Error:", error);
    throw error;
  }
};

