                         <span className="text-purple-400 text-xs animate-pulse font-bold tracking-widest">PROCESSING NEURAL PATHWAYS...</span>
                      </div>
                    ) : (
                      <MessageContent text={m.text} />
                    )}
                </div>
            </div>
