                        id: 'cloud-restore',
                        type: MessageType.SUCCESS,
                        content: `DATA RESTORED FROM CLOUD. SECTOR ${cloudMax} UNLOCKED.`,
                        timestamp: new Date().toLocaleTimeString()
                    }]
                }));
            } else {
                await saveProgress(false, user);
